import type { University, UniversityCategory, UniversityType } from '../types/university.types';

type Seed = [
  name: string,
  website: string,
  country: string,
  city: string,
  type: UniversityType,
  category: UniversityCategory,
  ranking: string,
  establishedYear: number | undefined,
  tags: string[],
  featured?: boolean,
  extra?: UniversityCategory[],
];

export const universitySubcategories: UniversityCategory[] = [
  'Pakistani Government Universities',
  'Pakistani Private Universities',
  'Engineering Universities',
  'Medical Universities',
  'Business Universities',
  'Islamic Universities',
  'International Universities',
  'Ivy League Universities',
  'Top Asian Universities',
  'Top European Universities',
  'Top Australian Universities',
  'Top Canadian Universities',
];

const slugify = (value: string) =>
  value
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

const domain = (website: string) => new URL(website).hostname.replace(/^www\./, '');

const makeUniversity = (seed: Seed): University => {
  const [name, website, country, city, type, category, ranking, establishedYear, tags, featured = false, extra = []] = seed;
  const subcategories = Array.from(new Set([category, ...extra]));

  return {
    id: slugify(name),
    slug: slugify(name),
    name,
    website,
    country,
    city,
    type,
    category,
    subcategories,
    ranking,
    establishedYear,
    verified: true,
    featured,
    tags: Array.from(new Set([type, country, ...tags])),
    logo: `https://www.google.com/s2/favicons?domain=${domain(website)}&sz=64`,
    description: `${name} is a verified ${type.toLowerCase()} university in ${city}, ${country}, listed with its official website and academic category for quick discovery.`,
  };
};

